def restore(dest: Path, force: bool) -> int:
    dest = dest.resolve()
    written = skipped = 0
    for rel, digest, size, payload in FILES:
        target = (dest / rel).resolve()
        if dest not in target.parents:
            sys.exit(f"Refusing unsafe path: {rel}")
        data = zlib.decompress(base64.b64decode(payload))
        if hashlib.sha256(data).hexdigest() != digest or len(data) != size:
            sys.exit(f"Bundle is corrupted at {rel}. Re-download veritas_repo_bundle.py.")
        if target.exists():
            if target.read_bytes() == data:
                skipped += 1
                continue
            if not force:
                sys.exit(f"{rel} already exists and differs. Use an empty folder or pass --force.")
        target.parent.mkdir(parents=True, exist_ok=True)
        target.write_bytes(data)
        written += 1
    for rel, digest, _, _ in FILES:   # second pass: verify what is on disk
        if hashlib.sha256((dest / rel).read_bytes()).hexdigest() != digest:
            sys.exit(f"Checksum mismatch after writing {rel}")
    print(f"Restored {written} files ({skipped} already identical) into {dest}; all checksums verified ({len(FILES)} total).")
    print("Next: cd backend && pip install -r requirements.txt -r requirements-dev.txt && pytest -q")
    return 0


def main() -> int:
    ap = argparse.ArgumentParser(description="Restore the Veritas repository from this bundle")
    ap.add_argument("--dest", default=".", help="destination folder (default: current folder)")
    ap.add_argument("--list", action="store_true", help="list files and exit")
    ap.add_argument("--force", action="store_true", help="overwrite existing files that differ")
    args = ap.parse_args()
    if args.list:
        for rel, _, size, _ in FILES:
            print(f"{size:>9}  {rel}")
        print(f"{len(FILES)} files")
        return 0
    return restore(Path(args.dest), args.force)


if __name__ == "__main__":
    raise SystemExit(main())
